    # Calls:
    # 1 - (200) POST:/json/status
    # 2 - (200) POST:/api/set_user_permission
    # 3 - (200) POST:/json/status
    # Found 1 potential fault of type-code 970
    @timeout_decorator.timeout(60)
    def test_50_post_on_status_stillAllowedAfterPermissionRevoked(self):
        
        headers = {}
        headers["content-type"] = "application/x-www-form-urlencoded"
        body = "username=pyload&password=pyload"
        cookies_pyload_jar = requests \
                .post(self.baseUrlOfSut + "/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_pyload = requests.utils.dict_from_cookiejar(cookies_pyload_jar)
        
        headers = {}
        headers["content-type"] = "application/x-www-form-urlencoded"
        body = "username=alice&password=alicepass"
        cookies_alice_jar = requests \
                .post(self.baseUrlOfSut + "/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_alice = requests.utils.dict_from_cookiejar(cookies_alice_jar)
        
        
        headers = {}
        headers['Accept'] = "*/*"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/json/status",
                    headers=headers, cookies=cookies_pyload, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 200
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["pause"] == True
        assert res_0.json()["active"] == 1
        assert res_0.json()["queue"] == 6580
        assert res_0.json()["total"] == 6580
        assert res_0.json()["speed"] == 0
        assert res_0.json()["download"] == False
        assert res_0.json()["reconnect"] == True
        assert res_0.json()["captcha"] == False
        assert res_0.json()["proxy"] == False
        
        headers = {}
        headers['Accept'] = "*/*"
        res_1 = requests \
                .post(self.baseUrlOfSut + "/api/set_user_permission?" + 
                    "user=pyload&" + 
                    "permission=1&" + 
                    "role=394",
                    headers=headers, cookies=cookies_alice, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 200
        assert "application/json" in res_1.headers["content-type"]
        assert "null" in res_1.text
        
        # Fault970. Stateful Authorization: privilege persists after a permission-reducing transition.
        headers = {}
        headers['Accept'] = "*/*"
        res_2 = requests \
                .post(self.baseUrlOfSut + "/json/status",
                    headers=headers, cookies=cookies_pyload, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_2.status_code == 200
        assert "application/json" in res_2.headers["content-type"]
        assert res_2.json()["pause"] == True
        assert res_2.json()["active"] == 1
        assert res_2.json()["queue"] == 6580
        assert res_2.json()["total"] == 6580
        assert res_2.json()["speed"] == 0
        assert res_2.json()["download"] == False
        assert res_2.json()["reconnect"] == True
        assert res_2.json()["captcha"] == False
        assert res_2.json()["proxy"] == False


